import copy
import os
import re
import subprocess
import shlex
import time

from docopt import docopt
import platform
from ute_common_abstract_core.logger import get_logging_path
from ta_messaging.message_types_utils import _map_user_protocol_to_database_protocols
from ta_messaging.message_containers import get_containers_for_msg, does_message_contain_parsable_containers
from ta_tshark_hex_parser.uesim_parser import UesimParser
from ta_messaging.py3_string import py3_string

UESIM_TMP_FILENAME = 'uesim.txt'
UESIM_DUMP_LOCATION = '/opt/emssim/util/uesim-dump'
UESIM_DUMP_PARSE_LINE = '@dump {protocol} {pdu_type} {hex}'
OUT_FILE_PREFIX = 'PARSED_'
OUT_FILE_EXTENSION = 'txt'
RECORD_ADD_FIELDS = {'parsed': ""}
CONTAINERS_PARSING_ENABLED = True
OUTCOME_OK = 'Parsing OK'
OUTCOME_TIMEOUT = 'Parsing stopped due to exceeding time limit'

USAGE = """
Parse suite logs

Usage:
    raw_log_parser.py   [--log-path=<log-path>] [--messages-filter=<messages-filter>] [--max-parsing-time=<max-parsing-time>]
    raw_log_parser.py -h | --help

Example:
    raw_log_parser.py

"""

OPTIONS = """
Options:
    -h --help                                                    Show this screen
    --log-path=<log-path>                                        Path to log
    -m <messages-filter>,--messages-filter=<messages-filter>     Filter for messages
    --max-parsing-time=<max-parsing-time>                       Time in seconds to break parsing to not hang testcase
"""


def enable_containers_parsing():
    global CONTAINERS_PARSING_ENABLED
    CONTAINERS_PARSING_ENABLED = True


def disable_containers_parsing():
    global CONTAINERS_PARSING_ENABLED
    CONTAINERS_PARSING_ENABLED = False


def parse_args(args):
    '''
    parses docopt args
    '''
    return {key.lstrip('-').replace('<', '').replace('>', '').replace('[', '').replace(']', ''): value for key, value in
            args.items()}


def create_doc():
    '''
    creates documentation
    '''
    usage = USAGE
    options = OPTIONS
    return usage + options


def read_log_path(arguments):
    '''
    reads data from files and returns list of lines
    '''
    data = []
    if os.path.exists(arguments['log-path']):
        with open(arguments['log-path'], 'r') as f:
            for line in f.readlines():
                data.append(line.strip().split(';'))
            return data
    else:
        raise Exception('Logfile: {} does not exists'.format(arguments['log-path']))


def is_set(key, arguments):
    '''
    check is key is available in dict and value is set
    '''
    return True if key in arguments and arguments[key] else False


def is_message_required(message, messages_required):
    '''
    check if user filtering conditions are fulfilled
    '''
    return True if (len(messages_required) == 0 or message in messages_required) else False


def parse_file(log_content, parser):
    '''
    Parses file content by regexp
    '''
    return re.findall(parser, log_content)


def get_messages(arguments, log_content):
    '''
    returns message records from list of csv lines
    '''
    protocols = []
    if is_set('messages-filter', arguments):
        messages_filter = arguments['messages-filter'].split(',')
    else:
        messages_filter = []
    columns = log_content[0]
    accepted_messages = []
    for record_line in log_content[1:]:
        record = {}
        for col in columns:
            record[col] = record_line[columns.index(col)]
            if col == 'protocol':
                protocols.append(record_line[columns.index(col)])
            record.update(copy.deepcopy(RECORD_ADD_FIELDS))
        if is_message_required(record['message_type'], messages_filter):
            accepted_messages.append(record)
    return accepted_messages, list(set(protocols))


def prepare_uesimp_dump_file(arguments, accepted_messages):
    '''
    Prepares csvn line for batch processing
    '''
    uesim_file_name = os.sep.join(arguments['log-path'].split(os.sep)[:-1] + [UESIM_TMP_FILENAME])
    with open(uesim_file_name, 'w') as file:
        for message_record in accepted_messages:
            file.write("{}\n".format(get_uesim_dump_parsing_line(message_record)))
    return uesim_file_name


def extract_msg_payload_from_uesim_dump_string(parsed_container):
    '''
    Cuts off redundant uesim-dump info lines from parsed_container
    '''
    return "\n".join(parsed_container.split('\n', 2)[1:])


def parse_containers_in_message(message_type, asn1_pdu):
    '''
    Parses hex containers included in asn1_pdu payload string
    '''
    containers_for_msg = get_containers_for_msg(message_type, asn1_pdu)
    tmp = asn1_pdu
    for container_parse_function in containers_for_msg:
        # first try to parse last container
        (field_index, hex_to_be_replaced, parsed_container) = container_parse_function(tmp)
        if parsed_container is None:
            # if fails, look again at entire message
            (field_index, hex_to_be_replaced, parsed_container) = container_parse_function(asn1_pdu)
        if parsed_container is not None:
            asn1_pdu += extract_msg_payload_from_uesim_dump_string(parsed_container)
            tmp = parsed_container
    return asn1_pdu


def translate_xap_protocol_to_useim_pdu_type(protocol):
    if protocol != 'xnap':
        return "{}-PDU".format(protocol.upper())
    else:
        return "XnAP-PDU"


def parse_pdu(arguments, parsing_start_time, accepted_messages, is_rrc_payload=False):
    '''
    parses pdu by invoking uesim_dump
    '''
    parser = UesimParser()
    exceptions_num = 0
    max_time = int(arguments['max-parsing-time']) if is_set('max-parsing-time', arguments) else None
    last_index = None
    for index, message_record in enumerate(accepted_messages):
        if is_rrc_payload is False:
            protocol = _map_user_protocol_to_database_protocols(message_record['protocol'])
            pdu_type = translate_xap_protocol_to_useim_pdu_type(protocol)
        else:
            pdu_type = message_record['uesim_type']
            protocol = parser._convert_rrc_type_to_uesim_rrc_type(message_record['protocol'])
            message_record['hex'] = parser._fix_payloads_for_specific_pdu_types(if_fix_payload=True,
                                                                                pdu_type=pdu_type,
                                                                                payload=message_record['hex'],
                                                                                rrc_type=message_record['protocol'])
        uesim_hex = UesimParser.UesimHexMsg(protocol=protocol,
                                            pdu_type=pdu_type,
                                            hex=message_record['hex']).dump_for_uesim()
        try:
            asn1_pdu = parser._convert_uesim_hex_msg2asn_value(uesim_hex)
            if CONTAINERS_PARSING_ENABLED:
                if does_message_contain_parsable_containers(message_record['message_type']):
                    try:
                        asn1_pdu = parse_containers_in_message(message_record['message_type'], asn1_pdu)
                    except Exception as container_parsing_exception:
                        message_record['parsed'] = "Failed to parse internal container due to: {}, uesim_hex={}"\
                            .format(container_parsing_exception, uesim_hex)
            message_record['parsed'] = extract_msg_payload_from_uesim_dump_string(asn1_pdu)
        except Exception as e:
            message_record['parsed'] = "Failed to parse whole message due to: {}, uesim_hex={}".format(e, uesim_hex)
            exceptions_num += 1
        if max_time is not None and int(time.time() - parsing_start_time) > max_time:
            message_record['parsed'] = "Parsing stopped due to time limit ({}s) exceeded".format(max_time)
            last_index = index
            break
    return accepted_messages, exceptions_num, last_index


def get_uesim_dump_parsing_line(message_record):
    '''
    gets uesim-dump parsing line
    '''
    protocol = _map_user_protocol_to_database_protocols(message_record['protocol'])
    pdu_type = "{}-PDU".format(protocol.upper())
    hex_value = message_record['hex']
    return UESIM_DUMP_PARSE_LINE.format(protocol=protocol, pdu_type=pdu_type, hex=hex_value)


def parse_uesim_file(uesim_file_name):
    '''
    parses file by uesim-dump
    '''
    assert os.path.exists(UESIM_DUMP_LOCATION), '{} script not avaialable'.format(UESIM_DUMP_LOCATION)
    command = shlex.split("{} {}".format(UESIM_DUMP_LOCATION, uesim_file_name))
    print(command)
    proc = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    stdout, stderr = proc.communicate()
    stdout = py3_string(stdout)
    stderr = py3_string(stderr)
    return stdout, stderr


def save_parsed_output(arguments, accepted_messages, last_index):
    '''
    Saves parsed csv file
    '''
    out_file = arguments['log-path'].split(os.sep)
    filename = out_file[-1]
    filename = "{}{}".format(OUT_FILE_PREFIX, filename)
    filename = re.sub(r'\.csv', '.{}'.format(OUT_FILE_EXTENSION), filename)
    out_file[-1] = filename
    out_filepath = os.sep.join(out_file)
    if last_index is None:
        iterated_messages = accepted_messages
    else:
        iterated_messages = accepted_messages[: int(last_index) + 1]
    with open(out_filepath, 'w+') as file:
        for a_message in iterated_messages:
            output = "{} {} {}\n{}".format(a_message['date'], a_message['time'],
                                           a_message['owner'] if 'owner' in a_message else "",
                                           a_message['parsed'])
            file.writelines(output)


def parse_csv_logs(csv_file_list, max_parsing_time=None):
    '''
    parses given files
    '''
    message = OUTCOME_OK
    parsing_start = time.time()
    for csv_file in csv_file_list:
        args = {'log-path': csv_file, 'max-parsing-time': max_parsing_time}
        main(args)
        if max_parsing_time is not None and int(time.time() - parsing_start) > int(max_parsing_time):
            message = OUTCOME_TIMEOUT
            break
    return message


def find_csv_logs(source_name=None):
    '''
    find csv logs within path
    '''
    log_path = get_logging_path()
    files = os.listdir(log_path)
    if source_name is None:
        csv_logs = [os.path.join(log_path, log) for log in files if '.csv' in log]
    else:
        csv_logs = [os.path.join(log_path, log) for log in files if '.csv' in log and source_name in log]
    return csv_logs


def parse_by_batch_file(accepted_messages):
    '''
    parses batch
    '''
    message = ""
    uesim_filename = prepare_uesimp_dump_file(arguments, accepted_messages)
    stdout, stderr = parse_uesim_file(uesim_filename)
    pdus = re.findall(r'value \w{2}AP-PDU.*?\@', stdout, re.MULTILINE | re.DOTALL)
    if len(pdus) != len(accepted_messages):
        message = 'Not all messages parsed, caught: {}, parsed: {}'.format(len(accepted_messages), len(pdus))
    return pdus, message


def parse_message_by_message(arguments, parsing_start_time, accepted_messages, protocols):
    '''
    parses one by one
    '''
    accepted_messages, exceptions_num, last_parsed_index = parse_pdu(arguments, parsing_start_time,
                                                                     accepted_messages,
                                                                     is_rrc_payload=True if 'rrc' in ",".join(protocols)
                                                                     else False)
    return accepted_messages, exceptions_num, last_parsed_index


def main(arguments):
    '''
    takes csv file input and return parsed file with messages
    '''
    parsing_start_time = time.time()
    log_content = read_log_path(arguments)
    accepted_messages, protocols = get_messages(arguments, log_content)
    accepted_messages, exceptions_num, last_parsed_index = parse_message_by_message(arguments, parsing_start_time,
                                                                                    accepted_messages, protocols)
    save_parsed_output(arguments, accepted_messages, last_parsed_index)
    if exceptions_num > 0:
        raise Exception('Could not parse {} messages. Remaining messages successfully parsed.'.format(exceptions_num))


if __name__ == '__main__':
    arguments = docopt(create_doc())
    arguments = parse_args(arguments)
    print(arguments)
    if platform.system() != 'Linux':
        path = "C:{}Users{}krawczuk{}Downloads{}messaging.log".format(os.sep, os.sep, os.sep, os.sep)
        arguments['log-path'] = path
    main(arguments)
